def clap(i):
    yt = lambda x: 72 - (x - 110) * 16 / 118
    x0 = 118 + 28 * i
    return P([(x0, round(yt(x0))), (x0 + 12, round(yt(x0 + 12))), (x0 + 18, round(yt(x0 + 18)) + 14), (x0 + 6, round(yt(x0 + 6)) + 14)], IN)


def stadium(x, y, w, h, c):
    r = w / 2
    top = [(round(x + r - r * math.cos(math.pi * i / 6)), round(y + r - r * math.sin(math.pi * i / 6))) for i in range(7)]
    bottom = [(round(x + r + r * math.cos(math.pi * i / 6)), round(y + h - r + r * math.sin(math.pi * i / 6))) for i in range(7)]
    return P(top + bottom, c)


def print_(cx, cy, c):
    return [O(cx, cy, 12, 20, c), O(cx - 9, cy - 26, 3, 4, c), O(cx - 3, cy - 30, 3, 4, c), O(cx + 4, cy - 29, 3, 4, c), O(cx + 10, cy - 24, 3, 3, c)]


def person(cx, b, s, c):
    return [O(cx, round(b - 56 * s), round(8 * s), round(8 * s), SK),
            P([(round(cx - 12 * s), round(b - 46 * s)), (round(cx + 12 * s), round(b - 46 * s)), (round(cx + 14 * s), b), (round(cx - 14 * s), b)], c)]


def house(x, w, wall, roof):
    y = 140 - round(0.7 * w)
    return [R(x, y, w, round(0.7 * w), wall), P([(x - 4, y), (x + w // 2, y - w // 2), (x + w + 4, y)], roof), R(x + w // 2 - 5, 126, 10, 14, BR)]


def stack(x, n):
    return [s for k in range(n) for s in (R(x - 20, 146 - 10 * k, 40, 9, OR), R(x - 20, 146 - 10 * k, 40, 2, SS))]


